using UnityEngine;
public class Script {
    public static object Main() {
        var go = GameObject.FindGameObjectWithTag("PlayerHead");
        if (go == null) return "Not Found";
        var result = go.name;
        Transform parent = go.transform.parent;
        while (parent != null) {
            result = parent.name + "/" + result;
            parent = parent.parent;
        }
        return result;
    }
}
